sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // Validate that this is a new non-standard software request
    if (current.request_type != 'non_standard' || current.state != 'submitted') {
        return;
    }

    // Initialize the workflow process
    try {
        gs.info('Starting non-standard software request workflow for: ' + current.number);

        // Set initial processing state
        current.state = 'processing';
        current.workflow_started = new GlideDateTime();
        current.update();

        // Start the workflow
        var workflow = new Workflow();
        workflow.startFlow('Non-Standard Software Request Workflow', current, current.operation());

        // Log workflow initiation
        gs.addInfoMessage('Non-standard software request workflow initiated for ' + current.software_name);

        // Create initial activity log entry
        var activityLog = new GlideRecord('sys_activity');
        activityLog.initialize();
        activityLog.table_name = 'x_custom_software_request';
        activityLog.table_sys_id = current.sys_id;
        activityLog.activity_type = 'workflow_started';
        activityLog.activity_date = new GlideDateTime();
        activityLog.activity_user = gs.getUserID();
        activityLog.activity_message = 'Workflow started for non-standard software request: ' + current.software_name;
        activityLog.insert();

    } catch (error) {
        gs.error('Failed to start workflow for non-standard software request: ' + error.toString());

        // Set error state
        current.state = 'workflow_error';
        current.workflow_error = error.toString();
        current.update();

        // Create incident for workflow failure
        var incident = new GlideRecord('incident');
        incident.initialize();
        incident.short_description = 'Workflow failed to start for software request: ' + current.number;
        incident.description = 'Error: ' + error.toString();
        incident.priority = '2';
        incident.urgency = '2';
        incident.impact = '2';
        incident.assignment_group = 'Software Support';
        incident.caller_id = current.requested_by;
        incident.insert();
    }

})(current, previous);

